begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000001601','setupai@test.local');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000001601','Setup AI','00000000-0000-4000-8000-000000001601');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000001601','00000000-0000-4000-8000-000000001601');
insert into public.entitlement_overrides(family_id,plan,reason,ends_at) values('10000000-0000-4000-8000-000000001601','plus','test',now()+interval '1 day');
update public.plans set setup_ai_monthly=2 where code='plus';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000001601","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000001601","role":"parent"}}',true);
select is((public.get_setup_ai_entitlement()->>'remaining')::int,2,'parent sees remaining allowance');
select throws_ok($$select public.get_setup_ai_entitlement('10000000-0000-4000-8000-000000009999')$$,'42501','forbidden','other family usage hidden');
select throws_ok($$select public.reserve_setup_ai('40000000-0000-4000-8000-000000001601','10000000-0000-4000-8000-000000001601',auth.uid(),'hash')$$,'42501',null,'client cannot reserve quota directly');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.reserve_setup_ai('40000000-0000-4000-8000-000000001601','10000000-0000-4000-8000-000000001601','00000000-0000-4000-8000-000000001601','hash')->>'ok','true','server reserves draft');
select is(public.reserve_setup_ai('40000000-0000-4000-8000-000000001601','10000000-0000-4000-8000-000000001601','00000000-0000-4000-8000-000000001601','hash')->>'error','generation_in_progress','retry cannot double-generate');
select is(public.reserve_setup_ai('40000000-0000-4000-8000-000000001602','10000000-0000-4000-8000-000000001601','00000000-0000-4000-8000-000000001601','hash2')->>'error','generation_in_progress','rapid requests are limited');
update public.setup_ai_jobs set updated_at=now()-interval '25 seconds' where id='40000000-0000-4000-8000-000000001601';
select is(public.reserve_setup_ai('40000000-0000-4000-8000-000000001602','10000000-0000-4000-8000-000000001601','00000000-0000-4000-8000-000000001601','hash2')->>'ok','true','second reservation allowed');
select is(public.reserve_setup_ai('40000000-0000-4000-8000-000000001603','10000000-0000-4000-8000-000000001601','00000000-0000-4000-8000-000000001601','hash3')->>'error','ai_quota_exceeded','in-flight drafts count against quota');
update public.setup_ai_jobs set status='done',result='{"suggestions":[]}' where id='40000000-0000-4000-8000-000000001601';
select ok(public.reserve_setup_ai('40000000-0000-4000-8000-000000001601','10000000-0000-4000-8000-000000001601','00000000-0000-4000-8000-000000001601','hash') ? 'cached','lost response returns saved draft');
select is(public.reserve_setup_ai('40000000-0000-4000-8000-000000001601','10000000-0000-4000-8000-000000001601','00000000-0000-4000-8000-000000001601','changed')->>'error','request_conflict','request id cannot change payload');
update public.setup_ai_jobs set status='failed' where id='40000000-0000-4000-8000-000000001602';
select is((public.get_setup_ai_entitlement('10000000-0000-4000-8000-000000001601')->>'remaining')::int,1,'failed request does not consume allowance');
update public.setup_ai_jobs set updated_at=now()-interval '25 seconds' where family_id='10000000-0000-4000-8000-000000001601';
update public.setup_ai_jobs set created_at=now()-interval '40 days' where id='40000000-0000-4000-8000-000000001602';
select is(public.reserve_setup_ai('40000000-0000-4000-8000-000000001602','10000000-0000-4000-8000-000000001601','00000000-0000-4000-8000-000000001601','hash2')->>'ok','true','failed prior-month request may be retried');
select is((public.get_setup_ai_entitlement('10000000-0000-4000-8000-000000001601')->>'remaining')::int,0,'retried request consumes current month allowance');
reset role;
select * from finish();
rollback;
